const express = require('express');
const diagnostics_channel = require('diagnostics_channel');

const app = express();
const webhookChannel = diagnostics_channel.channel('webhook:dispatch');

const webhookAuditBuffer = new Map();

webhookChannel.subscribe((event) => {
  webhookAuditBuffer.set(event.deliveryId, {
    endpoint: event.targetUrl,
    signatureHeader: event.hmacSignature,
    payloadBody: event.payloadJson,
    tenantId: event.tenantId
  });
});

app.get('/admin/diagnostics/webhooks/:deliveryId', (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const record = webhookAuditBuffer.get(req.params.deliveryId);
  if (!record) {
    return res.status(404).json({ error: 'Delivery log not found' });
  }

  // Validate tenant ownership and redact secret HMAC signature
  if (record.tenantId !== req.user.tenantId) {
    return res.status(403).json({ error: 'Forbidden: cannot inspect webhooks from another tenant' });
  }

  res.json({
    endpoint: record.endpoint,
    payloadBody: record.payloadBody,
    signatureHeaderMasked: record.signatureHeader.slice(0, 8) + '...'
  });
});

app.listen(7077);
